import {coinTypes,requests,pages,exchanges} from './coin-counter-content.mjs';
import {coinView,startCoinRound,nextCoinRequest,setCoinPage,selectCoinMat,addCoinSupport,resumeCoinRound,adjustCoin,exchangeResult,exchangeCoins,checkCoinPayments,checkMatchesCoins,coinTotal,coinCount} from './coin-counter-core.mjs';
import {hearButton} from './play-media.mjs';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const btn=(attrs,text,selected=false)=>`<button type="button" class="${selected?'primary':'secondary'}" ${attrs}>${esc(text)}</button>`;
const title=p=>p[0].toUpperCase()+p.slice(1);
const quantity=(n,unit)=>`${n} ${unit}${n===1?'':'s'}`;
const request=r=>requests.find(x=>x.id===r.request);
const help='Make two different ways to pay the price once. Mat A and mat B are alternatives: do not add them together. Count the coins separately from their value in cents. You can exchange coins without changing their total value.';
function coinArt(c){const scale=Math.min(c.diameter/24.26,1);return `<svg class="coin-face" viewBox="0 0 80 80" aria-hidden="true" focusable="false"><circle cx="40" cy="40" r="${scale*36}" fill="${esc(c.color)}" stroke="#183f39" stroke-width="2"/><circle cx="40" cy="40" r="${scale*30}" fill="none" stroke="#183f39" stroke-width="1"/><text x="40" y="46" text-anchor="middle" font-size="21" font-weight="bold" fill="#183f39">${c.value}¢</text></svg>`;}
function pictures(vector,types=coinTypes,emptyLabel='No coins yet'){return `<div class="coin-pictures" role="img" aria-label="${esc(types.map(c=>`${vector[c.id]??0} ${vector[c.id]===1?c.name.toLowerCase():c.plural}`).join(', '))}">${types.map(c=>Array.from({length:vector[c.id]??0},()=>coinArt(c)).join('')).join('')||`<span>${esc(emptyLabel)}</span>`}</div>`;}
function dots(value){return `<span class="coin-value-dots" role="img" aria-label="${quantity(value,'cent')} shown as ${quantity(value,'dot')}">${Array.from({length:value},()=>'<i aria-hidden="true"></i>').join('')}</span>`;}
function totals(v){return `<span><strong>${coinCount(v)}</strong> ${coinCount(v)===1?'coin':'coins'}</span><span><strong>${coinTotal(v)}</strong> ${coinTotal(v)===1?'cent':'cents'}</span>`;}
function mat(r,side,active,dotSupport){const v=r[side.toLowerCase()];return `<section class="coin-mat ${active?'coin-mat-active':'coin-mat-other'}" aria-label="Payment mat ${side}"><div class="coin-mat-heading">${btn(`data-coin-mat="${side}" aria-pressed="${active}"`,`Mat ${side}${active?' · editing':''}`,active)}<div class="coin-totals">${totals(v)}</div></div>${pictures(v)}${dotSupport?`<p class="tiny">Value dots: one dot is one cent, not one coin.</p>${dots(coinTotal(v))}`:''}${!active?`<p class="tiny">${coinTypes.map(c=>`${esc(c.name)}: ${v[c.id]??0}`).join('; ')}</p>`:''}</section>`;}
function coinGuide(r){return `<h2 id="coin-prompt" tabindex="-1">Meet our practice coins</h2><p>US cents: names and values stay here to help you.</p><div class="coin-guide">${coinTypes.map(c=>`<figure>${coinArt(c)}<figcaption><strong>${esc(c.name)}</strong><span>${c.value} ${c.value===1?'cent':'cents'}</span></figcaption>${r?.support.includes('dots')?dots(c.value):''}</figure>`).join('')}</div><p>One nickel and one dime are each <strong>one coin</strong>. The dime is smaller, but its value is larger: 10 cents instead of 5 cents.</p>${hearButton('A penny is one cent. A nickel is five cents. A dime is ten cents. A quarter is twenty-five cents. A dime is smaller than a nickel, but worth more.','Hear the coin names and values')}<p class="tiny">These practice pictures show names and values. Real coins may have different designs.</p>${btn('data-coin-page="make"','Make two payments',true)}`;}
function make(r,v){const vector=r[v.mat.toLowerCase()];return `<h2 id="coin-prompt" tabindex="-1">How could you pay ${quantity(r.price,'cent')}?</h2><p>Make A and B as two ways to pay once. They are not one combined payment.</p>${mat(r,v.mat,true,r.support.includes('dots'))}<div class="coin-editors" role="group" aria-label="Change mat ${v.mat}">${coinTypes.map(c=>`<div class="coin-editor">${coinArt(c)}<span><strong>${esc(c.name)}</strong><small>${c.value} ${c.value===1?'cent':'cents'} each</small></span>${btn(`data-coin-adjust="${c.id}" data-delta="-1" aria-label="Remove one ${esc(c.name)} from mat ${v.mat}"${(vector[c.id]??0)===0?' disabled':''}`,'−')}<strong aria-label="${vector[c.id]??0} ${esc(c.name)} ${vector[c.id]===1?'coin':'coins'}">${vector[c.id]??0}</strong>${btn(`data-coin-adjust="${c.id}" data-delta="1" aria-label="Add one ${esc(c.name)} to mat ${v.mat}"`,'＋')}</div>`).join('')}</div>${mat(r,v.mat==='A'?'B':'A',false,r.support.includes('dots'))}<details id="coin-exchanges"><summary>Exchange coins on mat ${v.mat}</summary><p>The value stays the same; the number of coins can change.</p><div class="coin-exchanges">${exchanges.map(e=>{const result=exchangeResult(vector,e.id);return btn(`data-coin-exchange="${e.id}"${result.ok?'':' disabled'}`,e.label);}).join('')}</div><p class="tiny">An exchange needs all its input coins and room for its result.</p></details><p class="tiny">Each mat holds at most 25 coins and 50 cents.</p>${btn('data-coin-page="compare"','Compare A and B',true)}`;}
const relationText={below:'below the price; add value or try a different combination',exact:'exactly the price',above:'above the price; remove value or try a different combination'};
function checkView(check,index,earlier){return `<section class="coin-check" tabindex="-1"><h3>${earlier?'Earlier check':'Latest check of these mats'}${index===null?'':` ${index+1}`}</h3>${['a','b'].map(side=>`<p><strong>Mat ${side.toUpperCase()}:</strong> ${quantity(check[side].count,'coin')}, ${quantity(check[side].value,'cent')}: ${relationText[check[`${side}Relation`]]}.</p>`).join('')}<p>${check.fulfilled?'Thank you! The market sign can show two different ways to pay.':check.aRelation==='exact'&&check.bRelation==='exact'&&!check.different?'Both payments are valid. Try another combination to show two different ways.':check.different?'These are different combinations. You can revise either mat.':'These are the same combination. You can explore another way.'}</p><p class="tiny">Recorded when checked. Later edits do not change this result.</p></section>`;}
function compare(r,v){const latest=r.checks.at(-1),matches=latest&&checkMatchesCoins(r);return `<h2 id="coin-prompt" tabindex="-1">Two ways to pay ${quantity(r.price,'cent')}</h2><p>Each mat pays once. Check each against the same price.</p><div class="coin-compare-mats">${mat(r,'A',v.mat==='A',r.support.includes('dots'))}${mat(r,'B',v.mat==='B',r.support.includes('dots'))}</div>${btn('data-coin-check','Check these payments',true)}${btn('data-coin-page="make"','Change the coins')}${latest?checkView(latest,null,!matches):'<p>No check yet. You can check, change the coins, or try another request.</p>'}${r.checks.length>1?`<details><summary>Earlier recorded checks (${r.checks.length-1})</summary>${r.checks.slice(0,-1).map((c,i)=>checkView(c,i,true)).join('')}</details>`:''}<p class="tiny">The latest 8 checks are kept. Checking again after 8 removes the oldest check.</p>`;}
function chooser(v){return `<section class="coin-new"><h2>Another pretend request</h2><p class="tiny">Up to 12 readable rounds stay here.${v.rounds.length>=12?' All 12 spaces are used. Starting a request removes the oldest readable round.':' Starting a request leaves earlier rounds waiting within that limit.'}</p><form id="coin-request-form"><label for="coin-request">Choose a stall request</label><select id="coin-request">${requests.map(x=>`<option value="${x.id}"${v.current?.request===x.id?' selected':''}>${esc(x.label)} · ${x.price} cents</option>`).join('')}</select><button type="submit" class="secondary" data-coin-choose>Start this request</button></form>${v.current?btn('data-coin-next','Another request'):''}</section>`;}
function history(v){return `${v.rounds.length?`<details class="coin-history"><summary>Our rounds (${v.rounds.length} of 12)</summary>${[...v.rounds].reverse().map(r=>`<p>${btn(`data-coin-resume="${r.id}"`,`Round ${r.id}: ${request(r)?.label||r.request}, ${quantity(r.price,'cent')}`)}</p>`).join('')}</details>`:''}${v.earlier.length?`<details><summary>Earlier unreadable work (${v.earlier.length})</summary><p>This original saved work stays unchanged.</p><pre>${esc(JSON.stringify(v.earlier,null,2))}</pre></details>`:''}`;}
export function coinCounterPage(state){const v=coinView(state),r=v.current;const heading=`<header class="page-heading"><a class="back" href="#workshop">← Workshop</a> <a class="back" href="#cafe">Back to Café</a> <a class="back" href="#workshop/change">Make change at the market</a><h1>The Coin Counter</h1><p>Borrow practice coins for our pretend market signs.</p></header>`;
 if(v.status==='unavailable')return `<div class="coin-page">${heading}<section class="coin-sheet"><h2>Earlier work is safe</h2><p>This saved Coin Counter uses a format we cannot continue here. It stays unchanged. The Workshop and Café are open.</p><details><summary>See saved work</summary><pre>${esc(JSON.stringify(state.coinCounter,null,2))}</pre></details></section></div>`;
 return `<div class="coin-page">${heading}<section class="coin-sheet"><nav class="coin-tabs" aria-label="Coin Counter pages">${pages.map(p=>btn(`data-coin-page="${p}" aria-current="${v.page===p?'page':'false'}"`,title(p),v.page===p)).join('')}</nav>${r?`<aside class="coin-ticket"><strong>${esc(request(r)?.label||r.request)}</strong><span>Pay <strong>${quantity(r.price,'cent')}</strong> once</span><small>Pretend stall materials · US cents</small></aside>`:''}<p class="coin-status" id="coin-status" role="status" tabindex="-1"></p>${v.page==='coins'?coinGuide(r):r?v.page==='compare'?compare(r,v):make(r,v):`<h2 id="coin-prompt" tabindex="-1">Choose a pretend request</h2><p>Borrow coins freely. There is no score, and the Café meals stay free of this practice.</p>`}${r?`<details id="coin-help"${r.support.includes('help')?' open':''}><summary>Help us think</summary><p>${help}</p>${hearButton(help,'Hear this help')}${btn(`data-coin-support="together"`,r.support.includes('together')?'Thinking together recorded':'We thought together',r.support.includes('together'))}</details>${btn(`data-coin-support="dots"`,r.support.includes('dots')?'Value dots are shown':'Show value dots',r.support.includes('dots'))}<p class="tiny">Value dots count cents, not coins. Names and values are supplied throughout this practice.</p>`:''}${chooser(v)}</section>${history(v)}</div>`;
}
export function coinCounterNotes(state){const v=coinView(state);if(v.status==='missing')return '';if(v.status==='unavailable')return `<details class="panel"><summary>Coin Counter · earlier format</summary><pre>${esc(JSON.stringify(state.coinCounter,null,2))}</pre></details>`;return `<details class="panel"><summary>Coin Counter (${v.rounds.length} rounds)</summary><p>Supported US-cent practice, not a measure of independent addition, real-coin recognition or money handling. Names and values are supplied. Support and familiar practice are separate records. Latest 12 readable rounds and 8 checks per round; full original work is in the notes download.</p>${v.rounds.map(r=>`<section><h3>Round ${r.id}: ${esc(request(r)?.label||r.request)}, ${quantity(r.price,'cent')}</h3><p>Familiar request: ${r.familiar?'yes':'no'}. Support: ${esc(r.support.join(', ')||'none recorded')}.</p><p>Live A: ${quantity(coinCount(r.a),'coin')}, ${quantity(coinTotal(r.a),'cent')}. Live B: ${quantity(coinCount(r.b),'coin')}, ${quantity(coinTotal(r.b),'cent')}.</p>${r.checks.map((c,i)=>checkView(c,i,i!==r.checks.length-1||!checkMatchesCoins(r))).join('')}</section>`).join('')}${v.earlier.length?`<pre>${esc(JSON.stringify(v.earlier,null,2))}</pre>`:''}</details>`;}
export function bindCoinCounter(state,{save,render,focus}){
 const show=(message='',target='#coin-prompt')=>{const open=[...document.querySelectorAll('.coin-page details[id][open]:not(#coin-help)')].map(x=>x.id);save();render();for(const id of open){const el=document.getElementById(id);if(el)el.open=true;}const status=document.querySelector('#coin-status');if(status)status.textContent=message;focus(target);};
 const bind=(selector,fn)=>document.querySelectorAll(selector).forEach(b=>b.addEventListener('click',()=>fn(b)));
 const start=id=>{const full=coinView(state).rounds.length>=12,r=startCoinRound(state,id);show(r?`A new request is ready.${full?' The oldest readable round was removed, as described.':''}`:'A new round cannot be created because its saved round numbers have reached the supported limit. Existing rounds remain available.',r?'#coin-prompt':'#coin-status');};
 bind('[data-coin-page]',b=>{setCoinPage(state,b.dataset.coinPage);show();});
 bind('[data-coin-mat]',b=>{selectCoinMat(state,b.dataset.coinMat);setCoinPage(state,'make');show(`Mat ${b.dataset.coinMat} selected.`, `[data-coin-mat="${b.dataset.coinMat}"]`);});
 bind('[data-coin-adjust]',b=>{const type=b.dataset.coinAdjust,delta=Number(b.dataset.delta),result=adjustCoin(state,type,delta),v=coinView(state),empty=delta===-1&&v.current?.[v.mat.toLowerCase()][type]===0;show(result==='limit'?'This mat can hold at most 25 coins and 50 cents. Remove or exchange a coin first.':result==='invalid'?'There is no coin to remove.':'Coins changed. Any earlier check stays unchanged.',`[data-coin-adjust="${type}"][data-delta="${empty?1:delta}"]`);});
 bind('[data-coin-exchange]',b=>{const result=exchangeCoins(state,b.dataset.coinExchange);show(result.ok?`This mat had ${quantity(result.beforeCount,'coin')} and now has ${quantity(result.afterCount,'coin')}. The value stays ${quantity(result.value,'cent')}.`:'This exchange needs its input coins and room within 25 coins and 50 cents.','#coin-exchanges > summary');});
 bind('[data-coin-check]',()=>{checkCoinPayments(state);show('These payments have been checked. The recorded result is below.','.coin-check');});
 bind('[data-coin-support]',b=>{addCoinSupport(state,b.dataset.coinSupport);show(b.dataset.coinSupport==='dots'?'Value dots show cents, not physical coins.':'Thinking together recorded.','#coin-status');});
 bind('[data-coin-next]',()=>start(nextCoinRequest(state)));
 document.querySelector('#coin-request-form')?.addEventListener('submit',e=>{e.preventDefault();start(document.querySelector('#coin-request').value);});
 bind('[data-coin-resume]',b=>{resumeCoinRound(state,Number(b.dataset.coinResume));show('Earlier round opened. Its recorded checks stay unchanged.');});
 document.querySelector('#coin-help')?.addEventListener('toggle',e=>{if(e.currentTarget.open){addCoinSupport(state,'help');save();}});
 document.querySelectorAll('.coin-page [data-speak]').forEach(b=>b.addEventListener('click',()=>{const missing=coinView(state).status==='missing';addCoinSupport(state,'audio');if(missing)setCoinPage(state,'coins');save();}));
}

// Shared original practice drawings; default Coin Counter rendering is unchanged.
export {coinArt as practiceCoinArt,pictures as practiceCoinPictures,dots as practiceCentDots};
